import { useState, useEffect } from "react";
import { MapContainer, TileLayer, CircleMarker, Popup, useMapEvents } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import { useNavigate } from "react-router-dom";
import "../styles/AdminDashboard.css";
import { Polygon } from 'react-leaflet';

const API_BASE = "http://localhost:8000";

export default function AdminDashboard() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("zones");
  const [districts, setDistricts] = useState([]);
  const [zones, setZones] = useState([]);
  const [territories, setTerritories] = useState([]);
  const [salesUsers, setSalesUsers] = useState([]);
  const [statistics, setStatistics] = useState({});
  const [pendingSales, setPendingSales] = useState([]);
  
  const [selectedDistrict, setSelectedDistrict] = useState(null);
  const [showZoneForm, setShowZoneForm] = useState(false);
  const [showDistrictForm, setShowDistrictForm] = useState(false);
  const [showActivityForm, setShowActivityForm] = useState(false);
  const [showCreateSalesForm, setShowCreateSalesForm] = useState(false);
  const [selectedZone, setSelectedZone] = useState(null);
  
  const [newDistrict, setNewDistrict] = useState({ code: "", name: "", center_lat: 0, center_lng: 0, total_area: 0 });
  const [newZone, setNewZone] = useState({ code: "", name: "", center_lat: 0, center_lng: 0, customers: 0, orders: 0, revenue: 0 });
  const [zoneActivity, setZoneActivity] = useState({ num_customers: 0, num_orders: 0, avg_order_value: 0, total_revenue: 0 });
  const [newSales, setNewSales] = useState({ username: "", email: "", password: "", full_name: "", phone: "" });
  
  const [algorithmResults, setAlgorithmResults] = useState(null);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  // Fetch data
  useEffect(() => {
    fetchDistricts();
    fetchSalesUsers();
    fetchStatistics();
    fetchPendingSales();
  }, []);

  useEffect(() => {
    if (selectedDistrict) {
      fetchZones(selectedDistrict);
      fetchTerritories(selectedDistrict);
    }
  }, [selectedDistrict]);

  const fetchDistricts = async () => {
    try {
      const res = await fetch(`${API_BASE}/districts`);
      if (!res.ok) throw new Error("Failed to fetch districts");
      const data = await res.json();
      setDistricts(data);
    } catch (err) {
      setError("Không thể tải danh sách districts");
    }
  };

  const fetchZones = async (districtId) => {
    try {
      const res = await fetch(`${API_BASE}/zones?district_id=${districtId}`);
      if (!res.ok) throw new Error("Failed to fetch zones");
      const data = await res.json();
      setZones(data);
    } catch (err) {
      setError("Không thể tải danh sách zones");
    }
  };

  const fetchTerritories = async (districtId) => {
    try {
      const res = await fetch(`${API_BASE}/territories?district_id=${districtId}`);
      if (!res.ok) throw new Error("Failed to fetch territories");
      const data = await res.json();
      setTerritories(data);
    } catch (err) {
      setError("Không thể tải danh sách territories");
    }
  };

  const fetchSalesUsers = async () => {
    try {
      const res = await fetch(`${API_BASE}/users?role=sales`);
      if (!res.ok) throw new Error("Failed to fetch sales users");
      const data = await res.json();
      setSalesUsers(data);
    } catch (err) {
      setError("Không thể tải danh sách sales users");
    }
  };

  const fetchStatistics = async () => {
    try {
      const res = await fetch(`${API_BASE}/admin/statistics`);
      if (!res.ok) throw new Error("Failed to fetch statistics");
      const data = await res.json();
      setStatistics(data);
    } catch (err) {
      setError("Không thể tải statistics");
    }
  };

  const fetchPendingSales = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await fetch(`${API_BASE}/admin/pending-sales`, {
        headers: { "Authorization": `Bearer ${token}` }
      });
      if (!res.ok) throw new Error("Failed to fetch pending sales");
      const data = await res.json();
      setPendingSales(data);
    } catch (err) {
      console.error("Error fetching pending sales:", err);
    }
  };

  // Map click handler: đặt center cho district mới khi click trên bản đồ
  function MapClickHandler() {
    useMapEvents({
      click(e) {
        setNewDistrict({ ...newDistrict, center_lat: e.latlng.lat, center_lng: e.latlng.lng });
      },
    });
    return null;
  }

  // District operations
  const handleAddDistrict = async () => {
    if (!newDistrict.code || !newDistrict.name) {
      setError("Vui lòng điền đầy đủ thông tin district");
      return;
    }
    try {
      const token = localStorage.getItem("token");
      const res = await fetch(`${API_BASE}/districts`, {
        method: "POST",
        headers: { 
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify(newDistrict),
      });
      if (!res.ok) throw new Error("Failed to create district");
      setSuccess("District được tạo thành công!");
      fetchDistricts();
      setNewDistrict({ code: "", name: "", center_lat: 0, center_lng: 0, total_area: 0 });
      setShowDistrictForm(false);
      setError("");
    } catch (err) {
      setError("Lỗi: " + err.message);
    }
  };

  // Zone operations
  const handleAddZone = async () => {
    if (!newZone.code || !newZone.name || !selectedDistrict) {
      setError("Vui lòng điền đầy đủ thông tin zone");
      return;
    }
    try {
      const token = localStorage.getItem("token");
      const res = await fetch(`${API_BASE}/zones`, {
        method: "POST",
        headers: { 
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify({
          zone_code: newZone.code,
          name: newZone.name,
          district_id: selectedDistrict,
          center_lat: parseFloat(newZone.center_lat),
          center_lng: parseFloat(newZone.center_lng),
          num_customers: parseInt(newZone.customers) || 0,
          num_orders: parseInt(newZone.orders) || 0,
          revenue: parseFloat(newZone.revenue) || 0
        }),
      });
      if (!res.ok) throw new Error("Failed to create zone");
      setSuccess("Zone được tạo thành công!");
      fetchZones(selectedDistrict);
      setNewZone({ code: "", name: "", center_lat: 0, center_lng: 0, customers: 0, orders: 0, revenue: 0 });
      setShowZoneForm(false);
      setError("");
    } catch (err) {
      setError("Lỗi: " + err.message);
    }
  };

  const handleAddZoneActivity = async () => {
    if (!selectedZone) {
      setError("Vui lòng chọn zone");
      return;
    }
    try {
      const token = localStorage.getItem("token");
      const res = await fetch(`${API_BASE}/zones/${selectedZone}/activities`, {
        method: "POST",
        headers: { 
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify(zoneActivity),
      });
      if (!res.ok) throw new Error("Failed to add activity");
      setSuccess("Activity được thêm thành công!");
      fetchZones(selectedDistrict);
      setZoneActivity({ num_customers: 0, num_orders: 0, avg_order_value: 0, total_revenue: 0 });
      setShowActivityForm(false);
      setSelectedZone(null);
      setError("");
    } catch (err) {
      setError("Lỗi: " + err.message);
    }
  };

  // Sales user operations
  const handleCreateSales = async () => {
    if (!newSales.username || !newSales.email || !newSales.password) {
      setError("Vui lòng điền đầy đủ thông tin");
      return;
    }
    try {
      const token = localStorage.getItem("token");
      const res = await fetch(`${API_BASE}/admin/create-sales`, {
        method: "POST",
        headers: { 
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify({
          username: newSales.username,
          email: newSales.email,
          password: newSales.password,
          full_name: newSales.full_name,
          phone: newSales.phone
        }),
      });
      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.detail || "Failed to create sales");
      }
      setSuccess("Sales account được tạo thành công!");
      fetchSalesUsers();
      setNewSales({ username: "", email: "", password: "", full_name: "", phone: "" });
      setShowCreateSalesForm(false);
      setError("");
    } catch (err) {
      setError("Lỗi: " + err.message);
    }
  };

  const handleApproveSales = async (userId, approve) => {
    try {
      const token = localStorage.getItem("token");
      const res = await fetch(`${API_BASE}/admin/approve-sales/${userId}`, {
        method: "POST",
        headers: { 
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify({ user_id: userId, is_approved: approve }),
      });
      if (!res.ok) throw new Error("Failed to approve");
      setSuccess(approve ? "Sales được duyệt!" : "Sales bị từ chối!");
      fetchPendingSales();
      setError("");
    } catch (err) {
      setError("Lỗi: " + err.message);
    }
  };

  // Algorithm operations
  const runKMeans = async () => {
    if (!selectedDistrict) {
      setError("Vui lòng chọn district");
      return;
    }
    try {
      const numClusters = prompt("Nhập số phân vùng:", "3");
      if (!numClusters) return;
      const token = localStorage.getItem("token");
      const res = await fetch(`${API_BASE}/algorithms/kmeans`, {
        method: "POST",
        headers: { 
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify({
          district_id: selectedDistrict,
          num_clusters: parseInt(numClusters),
          max_iterations: 100
        }),
      });
      if (!res.ok) throw new Error("Failed to run K-Means");
      const data = await res.json();
      setAlgorithmResults(data);
      setSuccess("K-Means hoàn tất: " + data.message);
      fetchTerritories(selectedDistrict);
      setError("");
    } catch (err) {
      setError("Lỗi: " + err.message);
    }
  };

  const runGreedy = async () => {
    if (!selectedDistrict) {
      setError("Vui lòng chọn district");
      return;
    }
    try {
      const numTerritories = prompt("Nhập số phân vùng:", "3");
      if (!numTerritories) return;
      const token = localStorage.getItem("token");
      const res = await fetch(`${API_BASE}/algorithms/greedy`, {
        method: "POST",
        headers: { 
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: JSON.stringify({
          district_id: selectedDistrict,
          num_territories: parseInt(numTerritories),
          max_zones_per_territory: 50
        }),
      });
      if (!res.ok) throw new Error("Failed to run Greedy");
      const data = await res.json();
      setAlgorithmResults(data);
      setSuccess("Greedy hoàn tất: " + data.message);
      fetchTerritories(selectedDistrict);
      setError("");
    } catch (err) {
      setError("Lỗi: " + err.message);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("role");
    localStorage.removeItem("user_id");
    navigate("/");
  };

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div className="header-content">
          <h1>🏢 Quản lý Hệ thống Territory Design</h1>
          <div className="header-info">
            <span className="user-info">👤 Admin</span>
            <button className="logout-btn" onClick={handleLogout}>Đăng xuất</button>
          </div>
        </div>
      </header>

      {error && <div className="error-message">{error}</div>}
      {success && <div className="success-message">{success}</div>}

      <div className="dashboard-wrapper">
        <aside className="sidebar">
          <nav className="nav-menu">
            <button
              className={`nav-item ${activeTab === "dashboard" ? "active" : ""}`}
              onClick={() => setActiveTab("dashboard")}
            >
              📊 Dashboard
            </button>
            <button
              className={`nav-item ${activeTab === "zones" ? "active" : ""}`}
              onClick={() => setActiveTab("zones")}
            >
              📍 Quản lý Zones
            </button>
            <button
              className={`nav-item ${activeTab === "territories" ? "active" : ""}`}
              onClick={() => setActiveTab("territories")}
            >
              🗺️ Quản lý Territories
            </button>
            <button
              className={`nav-item ${activeTab === "algorithms" ? "active" : ""}`}
              onClick={() => setActiveTab("algorithms")}
            >
              ⚙️ Chạy Algorithms
            </button>
            <button
              className={`nav-item ${activeTab === "sales" ? "active" : ""}`}
              onClick={() => setActiveTab("sales")}
            >
              👥 Quản lý Sales
            </button>
          </nav>
        </aside>

        <main className="main-content">
          {/* Dashboard Tab */}
          {activeTab === "dashboard" && (
            <div className="content-section">
              <h2>📊 Tổng quan Hệ thống</h2>
              <div className="stats-grid">
                <div className="stat-card">
                  <div className="stat-icon">📍</div>
                  <div className="stat-info">
                    <h3>Tổng Zones</h3>
                    <p className="stat-number">{statistics.total_zones || 0}</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">🗺️</div>
                  <div className="stat-info">
                    <h3>Tổng Territories</h3>
                    <p className="stat-number">{statistics.total_territories || 0}</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">👥</div>
                  <div className="stat-info">
                    <h3>Tổng Sales</h3>
                    <p className="stat-number">{statistics.total_sales || 0}</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">💰</div>
                  <div className="stat-info">
                    <h3>Tổng Revenue</h3>
                    <p className="stat-number">{(statistics.total_revenue || 0).toLocaleString()} VND</p>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Zones Management Tab */}
          {activeTab === "zones" && (
            <div className="content-section">
              <h3>Bản đồ Hà Nội (click để đặt tâm district mới)</h3>
              <div className="map-container">
                <MapContainer
                  center={
                    selectedDistrict
                      ? [
                          districts.find(d => d.id === selectedDistrict)?.center_lat || 21.0278,
                          districts.find(d => d.id === selectedDistrict)?.center_lng || 105.8342,
                        ]
                      : [newDistrict.center_lat || 21.0278, newDistrict.center_lng || 105.8342]
                  }
                  zoom={12}
                  style={{ height: '400px', width: '100%' }}
                >
                  <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

                  {/* Existing districts as circle markers */}
                  {districts.map(d => (
                    d.center_lat && d.center_lng ? (
                      <CircleMarker
                        key={d.id}
                        center={[d.center_lat, d.center_lng]}
                        radius={8}
                        pathOptions={{ color: selectedDistrict === d.id ? '#2b7cff' : '#d9534f' }}
                        eventHandlers={{ click: () => setSelectedDistrict(d.id) }}
                      >
                        <Popup>
                          <strong>{d.code}</strong>
                          <div>{d.name}</div>
                        </Popup>
                      </CircleMarker>
                    ) : null
                  ))}

                  {/* New district center preview */}
                  {newDistrict.center_lat !== 0 && newDistrict.center_lng !== 0 && (
                    <CircleMarker
                      center={[newDistrict.center_lat, newDistrict.center_lng]}
                      radius={10}
                      pathOptions={{ color: '#28a745' }}
                    >
                      <Popup>Vị trí district mới</Popup>
                    </CircleMarker>
                  )}

                  {/* Click handler to set center coords for new district */}
                  <MapClickHandler />
                </MapContainer>
              </div>
              <div className="section-header">
                <h2>📍 Quản lý Zones</h2>
                <div className="header-actions">
                  <button className="btn-primary" onClick={() => setShowDistrictForm(!showDistrictForm)}>
                    ➕ Thêm District
                  </button>
                  <button 
                    className="btn-primary" 
                    onClick={() => setShowZoneForm(!showZoneForm)}
                    disabled={!selectedDistrict}
                  >
                    ➕ Thêm Zone
                  </button>
                </div>
              </div>

              {/* District Selection */}
              <div className="section-content">
                <h3>Chọn District</h3>
                <div className="districts-grid">
                  {districts.map(d => (
                    <button
                      key={d.id}
                      className={`district-card ${selectedDistrict === d.id ? "selected" : ""}`}
                      onClick={() => setSelectedDistrict(d.id)}
                    >
                      <strong>{d.code}</strong>
                      <p>{d.name}</p>
                    </button>
                  ))}
                </div>
              </div>

              {/* Add District Form */}
              {showDistrictForm && (
                <div className="form-container">
                  <h3>Thêm District mới</h3>
                  <input
                    type="text"
                    placeholder="Code"
                    value={newDistrict.code}
                    onChange={(e) => setNewDistrict({ ...newDistrict, code: e.target.value })}
                  />
                  <input
                    type="text"
                    placeholder="Tên District"
                    value={newDistrict.name}
                    onChange={(e) => setNewDistrict({ ...newDistrict, name: e.target.value })}
                  />
                  <input
                    type="number"
                    placeholder="Latitude"
                    value={newDistrict.center_lat}
                    onChange={(e) => setNewDistrict({ ...newDistrict, center_lat: parseFloat(e.target.value) })}
                  />
                  <input
                    type="number"
                    placeholder="Longitude"
                    value={newDistrict.center_lng}
                    onChange={(e) => setNewDistrict({ ...newDistrict, center_lng: parseFloat(e.target.value) })}
                  />
                  <input
                    type="number"
                    placeholder="Diện tích"
                    value={newDistrict.total_area}
                    onChange={(e) => setNewDistrict({ ...newDistrict, total_area: parseFloat(e.target.value) })}
                  />
                  <div className="form-actions">
                    <button className="btn-success" onClick={handleAddDistrict}>Lưu</button>
                    <button className="btn-secondary" onClick={() => setShowDistrictForm(false)}>Hủy</button>
                  </div>
                </div>
              )}

              {/* Add Zone Form */}
              {showZoneForm && (
                <div className="form-container">
                  <h3>Thêm Zone mới</h3>
                  <input
                    type="text"
                    placeholder="Zone Code"
                    value={newZone.code}
                    onChange={(e) => setNewZone({ ...newZone, code: e.target.value })}
                  />
                  <input
                    type="text"
                    placeholder="Tên Zone"
                    value={newZone.name}
                    onChange={(e) => setNewZone({ ...newZone, name: e.target.value })}
                  />
                  <input
                    type="number"
                    placeholder="Latitude"
                    value={newZone.center_lat}
                    onChange={(e) => setNewZone({ ...newZone, center_lat: parseFloat(e.target.value) })}
                  />
                  <input
                    type="number"
                    placeholder="Longitude"
                    value={newZone.center_lng}
                    onChange={(e) => setNewZone({ ...newZone, center_lng: parseFloat(e.target.value) })}
                  />
                  <input
                    type="number"
                    placeholder="Số khách hàng"
                    value={newZone.customers}
                    onChange={(e) => setNewZone({ ...newZone, customers: parseInt(e.target.value) || 0 })}
                  />
                  <input
                    type="number"
                    placeholder="Số đơn hàng"
                    value={newZone.orders}
                    onChange={(e) => setNewZone({ ...newZone, orders: parseInt(e.target.value) || 0 })}
                  />
                  <input
                    type="number"
                    placeholder="Revenue"
                    value={newZone.revenue}
                    onChange={(e) => setNewZone({ ...newZone, revenue: parseFloat(e.target.value) || 0 })}
                  />
                  <div className="form-actions">
                    <button className="btn-success" onClick={handleAddZone}>Lưu</button>
                    <button className="btn-secondary" onClick={() => setShowZoneForm(false)}>Hủy</button>
                  </div>
                </div>
              )}

              {/* Zones List */}
              {selectedDistrict && (
                <div className="section-content">
                  <h3>Danh sách Zones</h3>
                  <table className="data-table">
                    <thead>
                      <tr>
                        <th>Code</th>
                        <th>Tên</th>
                        <th>Khách hàng</th>
                        <th>Đơn hàng</th>
                        <th>Revenue</th>
                        <th>Hành động</th>
                      </tr>
                    </thead>
                    <tbody>
                      {zones.map(z => (
                        <tr key={z.id}>
                          <td>{z.zone_code}</td>
                          <td>{z.name}</td>
                          <td>{z.num_customers}</td>
                          <td>{z.num_orders}</td>
                          <td>{z.revenue.toLocaleString()} VND</td>
                          <td>
                            <button 
                              className="btn-secondary" 
                              onClick={() => {
                                setSelectedZone(z.id);
                                setShowActivityForm(true);
                              }}
                            >
                              Thêm Activity
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}

              {/* Add Activity Form */}
              {showActivityForm && (
                <div className="form-container">
                  <h3>Thêm Activity cho Zone</h3>
                  <input
                    type="number"
                    placeholder="Số khách hàng"
                    value={zoneActivity.num_customers}
                    onChange={(e) => setZoneActivity({ ...zoneActivity, num_customers: parseInt(e.target.value) })}
                  />
                  <input
                    type="number"
                    placeholder="Số đơn hàng"
                    value={zoneActivity.num_orders}
                    onChange={(e) => setZoneActivity({ ...zoneActivity, num_orders: parseInt(e.target.value) })}
                  />
                  <input
                    type="number"
                    placeholder="Giá trị đơn hàng trung bình"
                    value={zoneActivity.avg_order_value}
                    onChange={(e) => setZoneActivity({ ...zoneActivity, avg_order_value: parseFloat(e.target.value) })}
                  />
                  <input
                    type="number"
                    placeholder="Tổng revenue"
                    value={zoneActivity.total_revenue}
                    onChange={(e) => setZoneActivity({ ...zoneActivity, total_revenue: parseFloat(e.target.value) })}
                  />
                  <div className="form-actions">
                    <button className="btn-success" onClick={handleAddZoneActivity}>Lưu</button>
                    <button className="btn-secondary" onClick={() => setShowActivityForm(false)}>Hủy</button>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Territories Management Tab */}
          {activeTab === "territories" && (
            <div className="content-section">
              <h2>🗺️ Quản lý Territories</h2>
              {selectedDistrict ? (
                <div>
                  <p>Chọn district: <strong>{districts.find(d => d.id === selectedDistrict)?.name}</strong></p>
                  <table className="data-table">
                    <thead>
                      <tr>
                        <th>Code</th>
                        <th>Sales</th>
                        <th>Zones</th>
                        <th>Khách hàng</th>
                        <th>Đơn hàng</th>
                        <th>Algorithm</th>
                      </tr>
                    </thead>
                    <tbody>
                      {territories.map(t => (
                        <tr key={t.id}>
                          <td>{t.territory_code}</td>
                          <td>{t.sales_id}</td>
                          <td>{t.num_zones}</td>
                          <td>{t.num_customers}</td>
                          <td>{t.num_orders}</td>
                          <td><span className="badge">{t.algorithm_used}</span></td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : (
                <p>Vui lòng chọn district để xem territories</p>
              )}
            </div>
          )}

          {/* Algorithms Tab */}
          {activeTab === "algorithms" && (
            <div className="content-section">
              <h2>⚙️ Chạy Algorithms</h2>
              {selectedDistrict ? (
                <div className="algorithms-grid">
                  <div className="algo-card">
                    <h3>🤖 K-Means Clustering</h3>
                    <p>Phân cụm zones dựa trên vị trí địa lý</p>
                    <button className="btn-primary" onClick={runKMeans}>Chạy K-Means</button>
                  </div>
                  <div className="algo-card">
                    <h3>🌱 Greedy Seed Growth</h3>
                    <p>Phân chia zones dựa trên cân bằng khối lượng công việc</p>
                    <button className="btn-primary" onClick={runGreedy}>Chạy Greedy</button>
                  </div>
                  <div className="algo-card">
                    <h3>🔍 Local Search</h3>
                    <p>Tối ưu hóa territories bằng cách đổi chỗ zones</p>
                    <button className="btn-primary" disabled>Chọn Territory để Chạy</button>
                  </div>
                </div>
              ) : (
                <p>Vui lòng chọn district để chạy algorithms</p>
              )}

              {algorithmResults && (
                <div className="algorithm-results">
                  <h3>📊 Kết quả Algorithms</h3>
                  <div className="result-info">
                    <p><strong>Algorithm:</strong> {algorithmResults.algorithm}</p>
                    <p><strong>Quality Score:</strong> {algorithmResults.quality_score?.toFixed(2)}%</p>
                    <p><strong>Execution Time:</strong> {algorithmResults.execution_time?.toFixed(3)}s</p>
                    <p><strong>Message:</strong> {algorithmResults.message}</p>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Sales Management Tab */}
          {activeTab === "sales" && (
            <div className="content-section">
              <div className="section-header">
                <h2>👥 Quản lý Sales</h2>
                <button className="btn-primary" onClick={() => setShowCreateSalesForm(!showCreateSalesForm)}>
                  ➕ Tạo Sales Account
                </button>
              </div>

              {showCreateSalesForm && (
                <div className="form-container">
                  <h3>Tạo Sales Account (Admin)</h3>
                  <input
                    type="text"
                    placeholder="Username"
                    value={newSales.username}
                    onChange={(e) => setNewSales({ ...newSales, username: e.target.value })}
                  />
                  <input
                    type="email"
                    placeholder="Email"
                    value={newSales.email}
                    onChange={(e) => setNewSales({ ...newSales, email: e.target.value })}
                  />
                  <input
                    type="password"
                    placeholder="Password"
                    value={newSales.password}
                    onChange={(e) => setNewSales({ ...newSales, password: e.target.value })}
                  />
                  <input
                    type="text"
                    placeholder="Họ tên"
                    value={newSales.full_name}
                    onChange={(e) => setNewSales({ ...newSales, full_name: e.target.value })}
                  />
                  <input
                    type="text"
                    placeholder="Số điện thoại"
                    value={newSales.phone}
                    onChange={(e) => setNewSales({ ...newSales, phone: e.target.value })}
                  />
                  <div className="form-actions">
                    <button className="btn-success" onClick={handleCreateSales}>Lưu</button>
                    <button className="btn-secondary" onClick={() => setShowCreateSalesForm(false)}>Hủy</button>
                  </div>
                </div>
              )}

              {/* Approved Sales */}
              <div className="section-content">
                <h3>✅ Sales đã được duyệt</h3>
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>ID</th>
                      <th>Username</th>
                      <th>Email</th>
                      <th>Họ tên</th>
                      <th>Số điện thoại</th>
                    </tr>
                  </thead>
                  <tbody>
                    {salesUsers.filter(s => s.is_approved).map(s => (
                      <tr key={s.id}>
                        <td>{s.id}</td>
                        <td>{s.username}</td>
                        <td>{s.email}</td>
                        <td>{s.full_name}</td>
                        <td>{s.phone}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {/* Pending Sales */}
              {pendingSales.length > 0 && (
                <div className="section-content">
                  <h3>⏳ Sales chờ duyệt ({pendingSales.length})</h3>
                  <table className="data-table">
                    <thead>
                      <tr>
                        <th>ID</th>
                        <th>Username</th>
                        <th>Email</th>
                        <th>Họ tên</th>
                        <th>Hành động</th>
                      </tr>
                    </thead>
                    <tbody>
                      {pendingSales.map(s => (
                        <tr key={s.id}>
                          <td>{s.id}</td>
                          <td>{s.username}</td>
                          <td>{s.email}</td>
                          <td>{s.full_name}</td>
                          <td>
                            <button className="btn-success" onClick={() => handleApproveSales(s.id, true)}>Duyệt</button>
                            <button className="btn-danger" onClick={() => handleApproveSales(s.id, false)}>Từ chối</button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          )}
        </main>
      </div>
    </div>
  );
}
